// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz: from address, the callee address (we will deploy a helper and pass its address),
    // an array length and a value v. Foundry fuzzer cannot directly synthesize calldata arrays,
    // so we fuzz a single address _to and an uint8 len to build an array; this keeps the deciding
    // inputs fuzzy while obeying the test harness rules.
    function testFuzz_property(address from, uint256 v, address _to, uint8 tosLen) public {
        // keep tosLen reasonable but wide (1..8) to ensure non-empty arrays and fuzz variety
        uint8 len = tosLen;
        if (len == 0) { len = 1; }
        if (len > 8) { len = 8; }

        // Build an array of addresses of length len filled with _to
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = _to;

        // Deploy a benign callee that will always accept the call and return true-like data.
        // This ensures the low-level call in C succeeds and transfer does not revert.
        CallerResponder okCallee = new CallerResponder();

        // Call c.transfer from any EOA (use vm.prank to set msg.sender if desired).
        // The function under test does not depend on msg.sender, so no need to prank.

        bool ok;
        try c.transfer(from, address(okCallee), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any admissible input where the call does not revert, the reference
        // implementation always returns true. We assert that the call did not revert (ok==true).
        // The mutant flips the returned boolean to false; therefore the mutant will violate this
        // property for some inputs (the fuzzer can find them). We assert the behavior observed
        // from c.transfer succeeded (didn't revert) — the reference satisfies this for all inputs
        // that meet the domain (non-empty _tos), and the mutant would still not revert but would
        // return false, thus differing. Checking non-revert via try/catch is valid per rules.
        assertTrue(ok);
    }
}

// Minimal benign callee that accepts the encoded selector and returns as if transferFrom succeeded.
contract CallerResponder {
    // Accept any call and return true-encoded data (abi.encode(true)).
    fallback() external payable returns (bytes memory) {
        // return abi-encoded true
        assembly {
            mstore(0x00, 1)
            return(0x00, 0x20)
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address (as caller), number of recipients and a seed to construct recipient addresses
    function testFuzz_property(address from, uint256 n, uint256 seed) public {
        // admissible domain: _tos.length must be > 0 per require in transfer
        uint256 len = bound(n, 1, 8); // keep arrays reasonably small but allow >1

        // build recipients array from fuzzed seed and len
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // derive addresses from seed so fuzzer can explore different lengths and addresses
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i, from)))));
        }

        // Deploy a benign callee that always returns true for the encoded selector
        // This models normal external contract that succeeds; mutant only changes behavior based on _tos.length
        BenignCallee good = new BenignCallee();

        // call c.transfer from arbitrary 'from' (we don't need vm.prank since transfer's caller is irrelevant here)
        bool ok;
        try c.transfer(from, address(good), tos, 1) {
            ok = true;
        } catch {
            ok = false; // should not revert for reference or mutant given benign callee and non-empty tos
        }

        // The universal property: for any non-empty tos and a callee that succeeds on each call, transfer returns true.
        // We observe this by ensuring the call does not revert (ok==true) and then calling transfer and checking its return value.
        // We must perform a second call to read the returned bool directly via try/catch with return value.
        bool ret;
        try c.transfer(from, address(good), tos, 1) returns (bool r) {
            ret = r;
        } catch {
            // if reference reverts this would fail the universal property; ensure test fails
            ret = false;
        }

        // Single assertion: on the correct contract, for any admissible inputs (non-empty tos and a callee that always succeeds), transfer returns true.
        // The mutant returns false when tos.length > 1, so this assertion will fail for those fuzzed inputs against the mutant.
        assertTrue(ret == true);
    }
}

// Minimal benign callee: always returns true for the encoded selector
contract BenignCallee {
    // Accept any calldata and return true (abi-encoded bool true)
    fallback() external payable returns (bytes memory) {
        // encode boolean true as return data
        bytes memory out = abi.encode(true);
        return out;
    }
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: from address, an element of _tos array, and a value v
    // We deploy a helper Callee that records the first two address args it was called with
    function testFuzz_property(address from, address potentialTo, uint256 v) public {
        // keep addresses non-zero to be meaningful
        vm.assume(from != address(0));
        vm.assume(potentialTo != address(0));

        // Deploy helper that will record the tuple of args passed in the low-level call
        Recorder rec = new Recorder();

        // Build array with single entry (we fuzz potentialTo as the element)
        address[] memory tos = new address[](1);
        tos[0] = potentialTo;

        // Call transfer on C pointing caddress to our Recorder
        // Use try/catch to capture possible revert (but Recorder will not revert)
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: the reference forwards (from, tos[0]) as the first two address args to the callee.
        // The Recorder exposes what it observed via public getters firstAddr() and secondAddr().
        // We assert that the call completed (ok == true) and that Recorder observed first==from and second==potentialTo.
        // This assertion is satisfied by the reference implementation for all inputs; the mutant that swaps the arguments
        // will cause Recorder to observe first==potentialTo and second==from for some inputs, breaking this assertion.
        assertTrue(ok && rec.firstAddr() == from && rec.secondAddr() == potentialTo);
    }
}

// Minimal helper that accepts the low-level call and decodes the arguments
contract Recorder {
    address public first;
    address public second;
    uint256 public valueArg;

    // The callee expects selector transferFrom(address,address,uint256)
    // We implement a fallback that tries to decode those args and store them.
    fallback() external payable {
        // The calldata layout is: 4 bytes selector, then abi-encoded (address,address,uint256)
        // We decode the calldata after the selector.
        if (msg.data.length >= 4 + 32 * 3) {
            bytes memory payload = msg.data[4:];
            // Use assembly to decode addresses and uint256 from payload
            address a;
            address b;
            uint256 v;
            assembly {
                a := mload(add(payload, 32))
                b := mload(add(payload, 64))
                v := mload(add(payload, 96))
            }
            first = a;
            second = b;
            valueArg = v;
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed inputs: an address 'from' (actor) and an array length n and a value v.
    // We cannot fuzz an address for the callee because an EOA always returns success for low-level call.
    // So we deploy a failing helper and pass its address as caddress, while still fuzzing other params.
    function testFuzz_property(address from, uint16 n, uint256 v) public {
        // Keep n in a reasonable wide bound but allow zero; we require _tos.length > 0 in contract, so exclude zero
        uint16 len = bound(n, 1, 10); // allow up to 10 targets

        // build an array of distinct addresses to pass as _tos; use the fuzzer-supplied 'from' to seed
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // create some pseudo-random but deterministic addresses from inputs; fuzz provides 'from' variety
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i, v)))));
        }

        // Deploy a helper that always reverts on the called selector
        Reverter reverter = new Reverter();
        address caddress = address(reverter);

        // Now call c.transfer and observe whether it reverts or not.
        // The general rule: reference C will revert (call fails) because it requires the callee call to succeed.
        // The mutant removes the require and will return true (no revert) even though callee reverted.

        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: the reference contract must revert the whole transfer when the callee reverts,
        // therefore ok must be false for ALL inputs (given we used a reverter callee and non-empty tos).
        // The mutant will sometimes make ok == true, causing this test to fail for that mutant.
        assertTrue(ok == false);
    }
}

// adversarial helper: always reverts on any call
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
